def parse_row(line: str) -> list[str]:
    fields = []
    current_field = ""
    in_quotes = False

    for char in line:
        if char == '"':
            if not in_quotes:
                # Check if next character is also a quote to avoid invalid quotes
                if (char == '"' and len(line) > 1 + 2):
                    continue

            current_field += char
            in_quotes = True
        elif char == ',' and not in_quotes:
            fields.append(current_field)
            current_field = ""

    # Add the last field if it exists
    if current_field:
        fields.append(current_field)

    return fields
```

