import re

def parse_money(s: str) -> float | None:
    if not s or s.startswith('$'):
        return None

    # Remove leading dollar sign
    s = s[1:]

    # Use regex to find the number part, allowing optional decimal point and commas as thousand separators
    match = re.search(r'\d+(?:\.\d+)?|\s*[,.]+', s)
    if not match:
        return None

    num_str = match.group()

    try:
        # Convert to float; this handles cases like "1234.50" correctly
        return float(num_str)
    except ValueError:
        return None
```

